-- الخطوة 2 (v2: LIKE بالبداية + معاملة مستقلة لكل صف) - دفعة 16/31 (4 صفوف)

-- id=60  المغيرة بن شعبة
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 60;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'المغيرة بن شعبة بن أبي عامر بن مسعود بن معتب بن مالك بن كعب بن عمرو بن سعد بن عوف ابن قيس وهو ثقيف الثقفي يكنى أبا عبد الله وقبل أبو عيسى وأمه أمامة بنت الأفقم ابن أبي عمر ومن بني نصر بن معاوية أسلم عام الخندق وشهد الحديبية وله في صلحها كلام مع عروة بن مسعود وقد ذكر في السير وكان يذكر أن رسول الله صلى الله عليه وسلم كناه أبا عيسى وكناه عمر بن الخطاب أبا عبد الله وكان موصوفا بالدهاء قال الشعبي

دهاة العرب أربعة معاوية بن أبي سفيان وعمرو بن العاص والمغيرة بن شعبة وزياد فأما معاوية بن أبي سفيان فللأناة والحلم وأما عمرو بن العاص فللمعضلات وأما المغيرة فللمبادهة وأما زياد فللصغير والكبير وكان قيس بن سعد بن عبادة من الدهاة المشهورين وكان أعظمهم كرما وفضلا قيل إن المغيرة أحصن؟ امرأة في الإسلام وقيل ألف امرأة وولاه عمر بن الخطاب البصرة ولم يزل عليها حتى شهد عليه بالزنى فعزله ثم ولاه الكوفة فلم يزل عليها حتى قتل عمر فأقره عثمان عليها ثم عزله وشهد اليمامة وفتوح الشام وذهبت عينه باليرموك وشهد القادسية وشهد فتح نهاوند وكان على ميسرة النعمان بن مقرن وشهد فتح همدان وغيرها واعتزل الفتنة بعد قتل عثمان وشهد الحكمين ولما سلم الحسن الأمر إلى معاوية استعمل عبد الله ابن عمرو بن العاص على الكوفة فقال المغيرة لمعاوية تجعل عمرا على مصر والمغرب وابنه على الكوفة فتكون بين فكي أسد فعزل عبد الله عن الكوفة واستعمل عليها المغيرة فلم يزل عليها إلى أن مات سنة خمسين روى عنه من الصحابة أبو أمامة الباهلي والمسور بن مخرمة وقرة المزني ومن التابعين أولاده عروة وحمزة وعفار وروى عنه مولاه وراد ومسروق وقيس بن أبي حازم وأبو وائل وغيرهم وهو أول من وضع ديوان البصرة وأول من رشى في الإسلام أعطى برقا حاجب عمر شيئا حتى أدخله إلى دار عمر أخبرنا إبراهيم بن محمد الفقيه وغير واحد بإسنادهم إلى محمد بن عيسى حدثنا أبو الوليد الدمشقي حدثنا الوليد بن مسلم قال أخبرني ثور بن يزيد عن رجاء بن حياة عن كاتب المغيرة وهو وراد عن المغيرة بن شعبة أن النبي صلى الله عليه وسلم مسح أعلى الخف وأسفله وتوفي بالكوفة سنة خمسين ولما توفي وقف مصقلة بن هبيرة الشيباني على قبره فقال

إن تحت الأحجار حزما وجوداوخصيما ألد ذا معلاقحية في الوجار أربد لاينفع منه السليم نفث الراقي
ثم قال أما والله لقد كنت شديد العداوة لمن عاديت شديد الأخوة لمن آخيت أخرجه الثلاثة'
WHERE id = 60
  AND content_ar LIKE '(ب د ع) المغيرة بن ش%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 60;

-- id=61  عبد الله بن الأرقم
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 61;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'عبد الله بن الأرقم بن عبد يغوث بن وهب بن عبد مناف بن زهرة بن كلاب بن مرة القرشي الزهري كانت آمنة بنت وهب أم رسول الله صلى الله عليه وسلم عمة أبيه الأرقم وأمه أميمة بنت حرب بن أبي همهمة بن عبد العزى الفهري وقيل عمرة بنت الأوقص بن هاشم بن عبد مناف أسلم عام الفتح وكتب للنبي صلى الله عليه وسلم ولأبي بكر وعمر رضي الله عنهما وأعطاه رسول الله صلى الله عليه وسلم بخيبر خمسين وسقا واستعمله عمر على بيت المال وعثمان بعده ثم إنه استعفى عثمان من ذلك فأعفاه ولما استكتبه رسول الله صلى الله عليه وسلم أمن إليه ووثق به فكان إذا كتب له إلى بعض الملوك يأمره أن يختمه ولا يقرؤه لأمانته عنده وروى مالك قال بلغني أنه ورد على النبي صلى الله عليه وسلم كتاب فقال من يجيب عنه فقال عبد الله بن الأرقم أنا فأجاب وأتى به النبي صلى الله عليه وسلم فأعجبه وأنفذه وكان عمر حاضرا فأعجبه ذلك من عبد الله حيث أصاب ما أراده رسول الله صلى الله عليه وسلم فلما ولي عمر استعمله على بيت المال

وروى مالك قال بلغني أن عثمان أجاز عبد الله بن الأرقم وهو على بيت المال بثلاثين ألفا فأبى أن يقبلها وروى عمرو بن دينار أن عثمان رضي الله عنه أعطاه ثلاثمائة ألف درهم فأبى أن يقبلها وقال عملت لله وإنما أجري على الله وقال له عمر بن الخطاب لو كان لك مثل سابقة القوم ما قدمت عليك أحدا وكان عمر يقول ما رأيت أخشى لله تعالى من عبد الله بن الأرقم وعمي قبل وفاته أخبرنا إسماعيل ابن علي بن عبيد الله وغير واحد قالوا بإسنادهم إلى أبي عيسى محمد بن عيسى حدثنا هناد حدثنا أبو معاوية عن هشام عن عروة عن أبيه عن عبد الله بن الأرقم قال أقيمت الصلاة فأخذ بيد رجل فقدمه وكان إمام القوم وقال سمعت رسول الله صلى الله عليه وسلم يقول إذا أقيمت الصلاة ووجد أحدكم الخلاء فليبدأ بالخلاء رواه شعبة والثوري والحمادان ومعمر وابن عيينة ومحمد بن إسحاق وغيرهم عن هشام بن عروة مثله ورواه وهيب وشعيب بن إسحاق وابن جريج في بعض الروايات عنه فقالوا عن هشام عن أبيه عن رجل عن عبد الله بن الأرقم ورواه أبو الأسود عن عروة عن عبد الله بن الأرقم ورواه أبو معشر عن هشام عن أبيه عن عائشة أخرجه الثلاثة'
WHERE id = 61
  AND content_ar LIKE '(ب د ع) عبد الله بن %'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 61;

-- id=62  شرحبيل بن حسنة
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 62;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'شرحبيل بن حسنة وهم أمه واسم أبيه

عبد الله بن المطاع بن عبد الله بن الغطريف بن عبد العزى بن جثامة بن مالك بن ملازم بن مالك بن رهم بن سعد بن يشكر بن مبشر بن الغوث بن مر أخي تميم بن مر وقيل إنه كندي وقيل تميمي وقيل غير ذلك يكنى أبا عبد الله وأمه حسنة مولاة لعمر ابن حبيب بن وهب بن حذافة الجمحي وكان شرحبيل حليفا لبني زهرة حالفهم بعد موت أخويه لأمه جنادة وجابر ابني سفيان بن معمر بن حبيب ولما مات عبد الله والد شرحبيل تزوج أمه حسنة أم شرحبيل رجل من الأنصار من بني زريق اسمه سفيان وكان يقال له سفيان بن معمر لأن معمرا تبناه وحالفه وزوجه حسنة ومعها شرحبيل فولدت له جابرا وجنادة ابني سفيان وأسلم شرحبيل قديما وأخواه وهاجر إلى الحبشة هو وأخواه فلما قدموا من الحبشة نزلوا في بني زريق في ربعهم ونزل شرحبيل مع أخويه لأمه ثم هلك سفيان وابناه في خلافة عمر رضي الله عنه ولم يتركوا عقبا فتحول شرحبيل بن حسنة إلى بني زهرة فحالفهم ونزل فيهم فخاصمهم أبو سعيد بن المعلى الزرقي إلى عمر وقال حليفي ليس له أن يتحول إلى غيري فقال شرحبيل ما كنت حليفا لهم وإنما نزلت مع أخوي فلما هلكا حالفت من أردت فقال عمر يا أبا سعيد إن جئت ببينة وإلا فهو أولى بنفسه فلم يأت ببينة فثبت شرحبيل على حلفه وقال الزبير إن حسنة زوجة سفيان بن معمر تبنت شرحبيل وليس بابن لها فنسب إليها وهي من أهل عدول ناحية من البحرين تنسب إليها السفن العدولية وقال أبو عمر كان شرحبيل من مهاجرة الحبشة ومن وجوه قريش وسيره أبو بكر وعمر على جيش إلى الشام ولم يزل واليا على بعض نواحي الشام لعمر إلى أن هلك في طاعون عمواس سنة ثمان عشرة وله سبع وستون سنة طعن هو وأبو عبيدة بن الجراح في يوم واحد أخبرنا أبو ياسر بن هبة الله الدقاق بإسناده عن عبد الله بن أحمد قال حدثني أبي حدثنا عبد الصمد حدثنا همام حدثنا قتادة عن شهر عن عبد الرحمن بن غنم قال لما وقع الطاعون بالشام خطب عمرو بن العاص الناس فقال إن هذا الطاعون رجس فتفرقوا عنه في هذه الشعاب وفي هذه الأودية فبلغ ذلك شرحبيل بن حسنة فغضب فجاء وهو يجر ثوبه معلق نعله بيده فقال صحبت رسول الله صلى الله عليه وسلم وعمرو أضل من حمار أهله ولكنه رحمة ربكم ودعوة نبيكم ووفاة الصالحين قبلكم أخرجه الثلاثة'
WHERE id = 62
  AND content_ar LIKE '(ب د ع) شرحبيل بن حس%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 62;

-- id=63  ثابت بن قيس بن شماس
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 63;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'ثابت ابن قيس بن شماس بن زهير بن مالك بن امرئ القيس بن مالك وهو الأغر بن ثعلبة ابن كعب بن الخزرج وأمه امرأة من طئ يكنى أبا محمد بابنه محمد وقيل أبو عبد الرحمن وكان ثابت خطيب الأنصار وخطيب النبي صلى الله عليه وسلم كما كان حسان شاعره وقد ذكرنا ذلك قبل وشهد أحدا وما بعدها وقتل يوم اليمامة في خلافة أبي بكر شهيدا أخبرنا أبو الفضل عبد الله بن أحمد بن عبد القاهر أخبرنا أبو محمد جعفر بن أحمد بن الحسين المقري أخبرنا الحسن بن أحمد بن شاذان أخبرنا عثمان بن أحمد بن السمال أخبرنا يحيى بن جعفر بن الزبرقان أخبرنا أزهر بن سعد عن ابن عون قال أنبأني موسى بن أنس عن أنس بن مالك أن رسول الله صلى الله عليه وسلم افتقد ثابت بن قيس فقال من يعلم لي علمه فقال رجل أنا يا رسول الله فذهب فوجده في منزله جالسا منكسا رأسه فقال ما شأنك قال شر كنت أرفع صوتي فوق صوت رسول الله صلى الله عليه وسلم فقد حبط عملي وأنا من أهل النار فرجع إلى رسول الله فأعلمه قال موسى ابن أنس فرجع إليه والله في المرة الأخيرة ببشارة عظيمة فقال اذهب فقل له لست من أهل النار ولكنك من أهل الجنة أخبرنا علي بن عبيد الله وإبراهيم بن محمد وأبو جعفر بإسنادهم عن أبي عيسى أخبرنا قتيبة أخبرنا عبد العزيز بن محمد عن سهيل بن أبي صالح عن أبيه عن أبي هريرة أن النبي صلى الله عليه وسلم قال نعم الرجل أبو بكر نعم الرجل عمر نعم الرجل أبو عبيدة نعم الرجل أسيد بن حضير نعم الرجل ثابت بن قيس نعم الرجل معاذ بن جبل نعم الرجل معاذ بن عمرو بن الجموح قال أنس بن مالك لما انكشف الناس يوم اليمامة قلت لثابت بن قيس بن شماس ألا ترى يا عم ووجدته يتحنط فقال ما هكذا كنا نقاتل مع رسول الله صلى الله عليه وسلم بئس ما عودتم أقرانكم وبئس ما عودتم أنفسكم اللهم إني أبرأ إليك مما جاء به هؤلاء يعني الكفار وأبرأ إليك مما يصنع هؤلاء يعني المسلمين ثم قاتل حتى قتل بعد أن ثبت هو وسالم مولى أبي حذيفة فقاتلا حتى قتلا وكان على ثابت درع له نفيسة فمر به رجل من المسلمين فأخذها فبينما رجل من المسلمين نائم أتاه ثابت في منامه فقال له إني أوصيك بوصية فإياك أن تقول

هذا حلم فتضيعه إني لما قتلت أمس مر بي رجل من المسلمين فأخذ درعي ومنزله في أقصى الناس وعند خبائه فرس يستن في طوله وقد كفأ على الدرع برمة وفوق البرمة رحل فأت خالدا فمره فليبعث فليأخذها فإذا قدمت المدينة على خليفة رسول الله صلى الله عليه وسلم يعني أبا بكر فقل له إن علي من الدين كذا وكذا وفلان من رقيقي عتيق وفلان فاستيقظ الرجل فأتى خالدا فأخبره فبعث إلى الدرع فأتي بها على ما وصف وحدث أبا بكر رضي الله عنه برؤياه فأجاز وصيته ولا نعلم أحدا أجيزت وصيته بعد موته سواه روى عنه أنس بن مالك وأولاده محمد ويحيى وعبد الله أولاد ثابت قتلوا يوم الحرة أخرجه الثلاثة'
WHERE id = 63
  AND content_ar LIKE '(ب د ع) ثابت ابن قيس%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 63;

